import React from 'react'
import 
logo from '../images/logo_header.png'

function Header() {
  return (
    <div style={{backgroundColor: 'black', marginRight: '7px'}}>
      <img src={logo} alt='logo' style={{height: 80}}></img>
      <Link to='/'>Home</Link>
    </div>
  )
}

export default Header
